// esbuild 打包脚本：把 nodejs/ 的第三方依赖打包成单文件 vendor.bundle.js
// 用法: node build-bundle.js
// 效果: node_modules/ 106MB 散文件 → ~10MB 单文件 bundle，APK 减约 20MB

import esbuild from 'esbuild'
import { existsSync, statSync } from 'fs'

const ENTRY = 'vendor-entry.js'  // 临时入口，导入所有第三方依赖

// 第三方依赖列表（从 index.js/agent.js/config.js 里提取的 await import() / require()）
const deps = [
  'deepagents',
  '@langchain/openai',
  '@langchain/core',
  '@langchain/langgraph',
  'zod',
  'langchain',
  // deepagents 的间接依赖
  'fast-glob',
  'micromatch',
  'yaml',
]

// 生成临时入口文件
import { writeFileSync, rmSync } from 'fs'
const entryContent = deps.map(d => 
  `export * from '${d}';`
).join('\n')
writeFileSync(ENTRY, entryContent)

console.log('[bundle] 开始打包', deps.length, '个依赖...')

try {
  // 同时输出 ESM 和 CJS 两份
  // ESM (.mjs): 给未来全切 ESM 用
  // CJS (.js):  业务代码当前仍用 require()，但关 minify 验证继承链问题
  const result = await esbuild.build({
    entryPoints: [ENTRY],
    bundle: true,
    format: 'esm',  // ESM 输出
    platform: 'node',
    target: 'node24',
    outfile: 'vendor.bundle.mjs',  // 明确 ESM 文件
    external: [
      'bridge',
      'node:*',
      'fs',
      'path',
      'os',
      'crypto',
      'util',
      'events',
      'stream',
      'url',
      'http',
      'https',
      'net',
      'tls',
      'zlib',
      'buffer',
      'child_process',
      'worker_threads',
      'async_hooks',
    ],
    packages: 'external' === 'bundle' ? undefined : undefined,
    minify: false,  // 关 minify，验证移动 V8 下 class 继承链是否完整
    sourcemap: false,
    legalComments: 'none',
    logLevel: 'info',
    banner: {
      js: '// Bundle for nodejs-mobile (Node 24) — generated by build-bundle.js',
    },
  })

  // 二次构建：CJS 版本（业务代码 require() 用）
  await esbuild.build({
    entryPoints: [ENTRY],
    bundle: true,
    format: 'cjs',
    platform: 'node',
    target: 'node24',
    outfile: 'vendor.bundle.js',
    external: [
      'bridge', 'node:*',
      'fs', 'path', 'os', 'crypto', 'util', 'events', 'stream', 'url',
      'http', 'https', 'net', 'tls', 'zlib', 'buffer',
      'child_process', 'worker_threads', 'async_hooks',
    ],
    minify: false,
    sourcemap: false,
    legalComments: 'none',
    logLevel: 'info',
  })

  const sizeMjs = statSync('vendor.bundle.mjs').size
  const sizeJs = statSync('vendor.bundle.js').size
  console.log('[bundle] ESM: vendor.bundle.mjs', (sizeMjs / 1024 / 1024).toFixed(2) + ' MB')
  console.log('[bundle] CJS: vendor.bundle.js', (sizeJs / 1024 / 1024).toFixed(2) + ' MB')
} catch (e) {
  console.error('[bundle] 失败:', e.message)
  process.exit(1)
} finally {
  rmSync(ENTRY)
}
